import sys

def is_palindrome(s):
    return s == s[::-1]

def solve():
    s = sys.stdin.readline().strip()
    k = int(sys.stdin.readline())

    n = len(s)
    if n % k != 0:
        print("NO")
        return

    length = n // k

    for i in range(k):
        start = i * length
        end = start + length
        substring = s[start:end]
        if not is_palindrome(substring):
            print("NO")
            return

    print("YES")

if __name__ == "__main__":
    solve()
"}

