{"code": "
import sys
import math

def is_prime(n):
    """Check if n is a prime number."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    sqrt_n = int(math.sqrt(n)) + 1
    for i in range(3, sqrt_n, 2):
        if n % i == 0:
            return False
    return True

def factorize(n):
    """Return the prime factorization of n as a dictionary."""
    factors = {}
    # Check for factor 2
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n //= 2

    # Check for odd factors
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
        i += 2

    # If n is a prime greater than 2
    if n > 1:
        factors[n] = 1

    return factors

def largest_lovely_number(n):
    """Find the largest lovely number that divides n."""
    if n == 1:
        return 1

    # Factorize n
    factors = factorize(n)

    # The largest lovely number is the product of distinct prime factors
    lovely = 1
    for prime in factors:
        lovely *= prime

    return lovely

# Read input and output result
if __name__ == "__main__":
    n = int(sys.stdin.readline())
    print(largest_lovely_number(n))
