import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    # Read tree structure
    tree = []
    parent = {}
    for i in range(n):
        v = int(next(it))
        l = int(next(it))
        r = int(next(it))
        tree.append((v, l, r))

        # Track parents
        if l != -1:
            parent[l] = i + 1  # 1-indexed
        if r != -1:
            parent[r] = i + 1

    # Find root (the node that is not a child of any other node)
    root = None
    for i in range(1, n + 1):
        if i not in parent:
            root = i
            break

    # Simulate search for each node
    failures = 0
    for node_idx in range(1, n + 1):
        # Get node information
        v, l, r = tree[node_idx - 1]

        # Simulate search
        current = root
        found = False
        while current != -1:
            current_v, current_l, current_r = tree[current - 1]

            if current_v == v:
                found = True
                break

            if v < current_v:
                # Go to left child
                current = current_l
            else:
                # Go to right child
                current = current_r

        if not found:
            failures += 1

    print(failures)

if __name__ == "__main__":
    solve()
"}

