def solve():
    n = int(input())

    # Strategy: Alternate between even and odd numbers to maximize XOR
    # This is a common strategy for XOR maximization problems

    # Create two lists: one for even numbers, one for odd numbers
    evens = []
    odds = []

    for i in range(n + 1):
        if i % 2 == 0:
            evens.append(i)
        else:
            odds.append(i)

    # Interleave the two lists to maximize XOR
    result = []
    while evens or odds:
        if evens:
            result.append(evens.pop(0))
        if odds:
            result.append(odds.pop(0))

    # Calculate the beauty
    beauty = 0
    for i in range(len(result) - 1):
        beauty += result[i] ^ result[i + 1]

    print(beauty)
    print(' '.join(map(str, result)))

