# We need to count the number of 1s in the range [l, r] of the final sequence
# The final sequence is formed by expanding n recursively

# For n = 0 or n = 1, the final sequence is just [n]
if n == 0 or n == 1:
    if l == 1 and r == 1:
        print(1 if n == 1 else 0)
    else:
