    """Check if a subarray is bad"""
    n = len(subarray)
    if n < 3:
        return False

    # Check if there exists i < j < k such that subarray[i] <= subarray[j] <= subarray[k]
    # This means subarray[j] lies on the manhattan path between subarray[i] and subarray[k]
    for j in range(1, n - 1):
        left = subarray[0:j]
        right = subarray[j:]
        if any(left[i] <= subarray[j] <= right[i] for i in range(len(left))):
            return True
    return False

