def count_ones(n, l, r):
    if n == 0:
        return 0
    if n == 1:
        return 1 if l <= 1 <= r else 0

    # Length of the list for n-1
    len_n_minus_1 = 3 * len_n_minus_1 + 1

    # Actually, we need to calculate length recursively
    def length(n):
        if n == 0:
            return 1
        if n == 1:
            return 1
        return 3 * length(n - 1) + 1

    len_n_minus_1 = length(n - 1)

    # Count ones in the range
    count = 0

    # First half
    if r <= len_n_minus_1:
        count += count_ones(n - 1, l, r)
    elif l > len_n_minus_1:
        count += count_ones(n - 1, l - len_n_minus_1 - 1, r - len_n_minus_1 - 1)
