            if grid[i * m + j] == '#':
                col_black_rows.add(i)
        if col_black_rows:
            black_cols.append((j, col_black_rows))

    # Check consistency
    for row_idx, row_cols in black_rows:
        for col_idx in row_cols:
            # Check if all black cells in this column are exactly the rows in this row's set
            expected_rows = row_cols
            actual_rows = black_cols[col_idx][1] if col_idx < len(black_cols) else set()
