import sys

def solve(s):
    n = len(s)

    # If the entire number is divisible by 3, we can just take it as one part
    if int(s) % 3 == 0:
        return 1

    # Otherwise, try to make cuts
    count = 0
    i = 0

    while i < n:
        # Try to find the smallest segment starting at i that is divisible by 3
        for j in range(i, n):
            if int(s[i:j+1]) % 3 == 0:
                count += 1
                i = j + 1
                break
        else:
            # No segment found, we can't make any more parts
            break

    return count

def main():
