import math

def solve() -> None:
    data = input().strip().split()
    if not data:
        return

    n = int(data[0])
    a = int(data[1])
    d = int(data[2])

    results = []

    for i in range(n):
        if i < len(data) - 2 * i:
            ti = int(data[2 * i + 3])
            vi = int(data[2 * i + 4])
        else:
            # Handle cases where we might go out of bounds
            ti = int(data[2 * i + 3])
            vi = int(data[2 * i + 4])

        # Calculate time to reach the station if traveling alone
        vi_sq_over_2a = vi * vi / (2.0 * a)

        if vi_sq_over_2a >= d:
            # Doesn't reach maximum speed
            t_alone = math.sqrt(2.0 * d / a)
        else:
            # Reaches maximum speed
            t_alone = d / float(vi) + vi / (2.0 * a)

        # Calculate arrival time (considering previous trolleybus)
        if i == 0:
            arrival = ti + t_alone
        else:
            arrival = max(ti + t_alone, results[-1])

        results.append(arrival)

    # Print results with enough precision
    for result in results:
        print(f"{result:.10f}")

if __name__ == "__main__":
    solve()
