def can_split(p, n):
    """Check if permutation p of length 2n can be split into two arrays a and b
    of length n each such that p = merge(a, b)."""
    if n == 0:
        return True

    if n == 1:
        # For n=1, we have exactly 2 elements
        if len(p) < 2:
            return False
        return p[0] < p[1]

    # Try both possibilities for the first element
    # Case 1: p[0] is from array a (so a[0] < b[0])
    # Then the rest of p should be merge(a[1:], b)
    # We need to check if the remaining elements can be split appropriately

    # Case 2: p[0] is from array b (so b[0] < a[0])
    # Then the rest of p should be merge(a, b[1:])

    if p[0] < p[1]:
        # Try to find where the split occurs
        min_rest = min(p[1:])
        min_index = p[1:].index(min_rest)

        # Check if we can split the remaining elements
        if len(p[1:]) >= n and min_index >= n - 1:
