def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    idx = 1

    # Group by political views
    views = {
        '11': [],
        '10': [],
        '01': [],
        '00': []
    }

    for _ in range(n):
        s = data[idx]
        a = int(data[idx + 1])
        idx += 2
        views[s].append(a)

    # Sort each view by influence (descending)
    for v in views.values():
        v.sort(reverse=True)

