    # Try all combinations of '11', '10', '01' people
    # We only need to try up to n/2 people for each view
    for x in range(len(views['11']) + 1):
        for y in range(len(views['10']) + 1):
            for z in range(len(views['01']) + 1):
                # Check if we have enough people
                if x + y + z == 0:
