    bar = input().strip()

    # Convert to binary lists for easier manipulation
    initial = [[int(board[i][j]) for j in range(N)] for i in range(N)]
    final = [[int(target[i][j]) for j in range(N)] for i in range(N)]
    bar = [int(bar[j]) for j in range(N)]

    # Function to apply bar to a row
    def apply_row(i):
        for j in range(N):
            if bar[j] != initial[i][j]:
                initial[i][j] ^= 1

    # Function to apply bar to a column
    def apply_col(j):
        for i in range(N):
            if bar[i] != initial[i][j]:
                initial[i][j] ^= 1

    # We need to transform initial to final
    # Let's try to solve this greedily

    # First try applying rows
    operations = []
    for i in range(N):
        if initial[i] != final[i]:
            # Apply row i
            apply_row(i)
            operations.append(f"row {i}")

    # Now check if we need to apply columns
    for j in range(N):
        if all(initial[i][j] == final[i][j] for i in range(N)):
