    if not data:
        return

    n = int(data[0])

    events = []
    for i in range(1, 2 * n + 1):
        if i >= len(data):
            break

        if data[i] == '+' or data[i] == '-':
            events.append(data[i])

            # Extract price if it's a '- x' event
            if data[i] == '-':
                if i + 1 < len(data):
                    price = int(data[i + 1])
                    events.append(price)
                else:
                    # Invalid format, but problem says it's guaranteed
                    pass

    placed = set()
    order = []
    valid = True

    idx = 0
    for _ in range(n):
        # Process '+' event
        if idx >= len(events) or events[idx] != '+':
            # Not a '+' event, but we need one
            valid = False
            break

        idx += 1

        # Place a shuriken
        # We'll just place them in order 1 to n for simplicity
        next_price = 1
        while next_price in placed:
            next_price += 1

        placed.add(next_price)
        order.append(next_price)

    # Process '-' events
    for _ in range(n):
        while idx < len(events) and events[idx] == '+':
            idx += 1

        if idx >= len(events):
            valid = False
            break

        if events[idx] == '-':
            idx += 1
            if idx >= len(events):
                # No price given
                valid = False
                break

            x = events[idx]
            if not isinstance(x, int):
                # Actually, we should check earlier
                valid = False
                break

            # Check if all prices < x have been placed
            for price in range(1, x):
                if price not in placed:
                    valid = False
                    break

    if valid:
        print("YES")
        print(" ".join(map(str, order)))
    else:
        print("NO")

