def smallest_multiple(n, p):
    """Find the smallest multiple of p that is >= n"""
    if n % p == 0:
        return n
    return n + (p - n % p)

def is_prime(n):
    """Check if n is prime"""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

# Generate all primes up to 10^6 using sieve
primes = []
for i in range(2, 10**6 + 1):
    if is_prime(i):
        primes.append(i)

