    if p >= X2:
        break
    # Check if p can lead to X2
    # X2 = smallest multiple of p >= X1
    # So X1 can be in the range [X2 - (p - 1), X2]
    for X1_candidate in range(X2 - (p - 1), X2 + 1):
        if X1_candidate < p:
            continue
        if smallest_multiple(X1_candidate, p) == X2:
            possible_X1.add(X1_candidate)

