import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        W = int(data[idx + 1])
        idx += 2

        weights = []
        for i in range(n):
            weights.append((int(data[idx + i]), i + 1))  # (weight, index)
        idx += n

        # Check if impossible
        if all(w > W for w, _ in weights):
            results.append("-1")
            continue

        # Check if we can take exactly W
        for w, idx in weights:
            if w == W:
                results.append(f"{1}\n{idx}")
                break
        else:
            # Try greedy approach
            weights.sort(reverse=True)
            taken = []
            total = 0

            # Try taking items until we either reach W or pass ⌈W/2⌉
            for i, (w, idx) in enumerate(weights):
                if total + w > W:
                    # We've gone over W, try removing the lightest we took
                    if total >= (W + 1) // 2:
                        # We have at least ⌈W/2⌉, just remove the lightest
                        # but we need to check if we can actually remove it
                        # (i.e., we took at least one item)
                        if taken:
                            taken.pop()  # Remove the lightest
                            results.append(f"{len(taken)}\n" + ' '.join(str(idx) for (w, idx) in taken))
                            break
                    else:
                        # We can't even reach ⌈W/2⌉, try a different approach
                        # Take all items
                        if total >= (W + 1) // 2:
                            results.append(f"{len(taken)}\n" + ' '.join(str(idx) for (w, idx) in taken))
                        else:
                            results.append("-1")
                        break

                taken.append((w, idx))
                total += w

                if total == W:
                    results.append(f"{len(taken)}\n" + ' '.join(str(idx) for (w, idx) in taken))
                    break
                elif total > (W + 1) // 2 and total <= W:
                    # We have at least ⌈W/2⌉, we need to check if we can remove the lightest
                    # and still be at least ⌈W/2⌉
                    if taken:
                        # Try removing the lightest
                        lightest = min(taken, key=lambda x: x[0])
                        if total - lightest[0] >= (W + 1) // 2:
                            taken.remove(lightest)
                            results.append(f"{len(taken)}\n" + ' '.join(str(idx) for (w, idx) in taken))
                            break
                        else:
                            # Can't remove lightest, try removing another
                            for item in taken:
                                if total - item[0] >= (W + 1) // 2:
                                    taken.remove(item)
                                    results.append(f"{len(taken)}\n" + ' '.join(str(idx) for (w, idx) in taken))
                                    break
                            else:
                                # No valid removal, try taking all
                                if total >= (W + 1) // 2:
                                    results.append(f"{len(taken)}\n" + ' '.join(str(idx) for (w, idx) in taken))
                                else:
                                    results.append("-1")
                            break
                    else:
                        # No items to remove, just output
                        results.append(f"{len(taken)}\n" + ' '.join(str(idx) for (w, idx) in taken))
                    break
            else:
                # We didn't break out of the loop, check if we have a valid solution
                if total >= (W + 1) // 2:
                    results.append(f"{len(taken)}\n" + ' '.join(str(idx) for (w, idx) in taken))
                else:
                    results.append("-1")

    sys.stdout.write("\n".join(results))

