import sys

def is_win(board, player):
    """Check if the given player has won"""
    # Check rows
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] == player:
            return True

    # Check columns
    for j in range(3):
        if board[0][j] == board[1][j] == board[2][j] == player:
            return True

    # Check diagonals
    if board[0][0] == board[1][1] == board[2][2] == player:
        return True
    if board[0][2] == board[1][1] == board[2][0] == player:
        return True

    return False

def solve():
    board = []
    for _ in range(3):
        line = sys.stdin.readline().strip()
        board.append(list(line))

    x_count = sum(row.count('X') for row in board)
    o_count = sum(row.count('0') for row in board)

    # Check if the board is illegal
    if x_count not in (o_count, o_count + 1):
        print("illegal")
        return

    # Check if someone has won
    x_won = is_win(board, 'X')
    o_won = is_win(board, '0')

    if x_won:
        if x_count == o_count:
            print("illegal")
        else:
            print("the first player won")
        return

    if o_won:
        if o_count == x_count:
            print("illegal")
        else:
            print("the second player won")
        return

    # Check if the game is over (draw)
    if x_count + o_count == 9:
        print("draw")
        return

    # Determine whose turn is next
    if x_count == o_count:
        print("first")
    else:
        print("second")

if __name__ == "__main__":
    solve()
"}

