    graph = [[] for _ in range(n)]
    for i in range(n):
        row = next(it)
        for j in range(n):
            if row[j] == '1':
                graph[i].append(j)

    # Find connected components using BFS
    visited = [False] * n
    components = []

    for start in range(n):
        if not visited[start]:
            # BFS to find component
            queue = [start]
            visited[start] = True
            component = [start]

            while queue:
                u = queue.pop(0)
                for v in graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        component.append(v)
                        queue.append(v)

            components.append(component)

