import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        a = list(map(int, data[idx:idx+n]))
        idx += n

        # Separate even and odd numbers
        evens = []
        odds = []
        for num in a:
            if num % 2 == 0:
                evens.append(num)
            else:
                odds.append(num)

        # Sort in descending order
        evens.sort(reverse=True)
        odds.sort(reverse=True)

        # Alice's turn (even)
        alice = 0
        bob = 0
        turn = 0  # 0 for Alice, 1 for Bob

        # Game loop
        while evens or odds:
            if turn == 0:  # Alice's turn
                if evens:
                    alice += evens.pop(0)
                else:
                    # No even numbers left, Bob takes odd
                    if odds:
                        bob += odds.pop(0)
            else:  # Bob's turn
                if odds:
                    bob += odds.pop(0)
                else:
                    # No odd numbers left, Alice takes even
                    if evens:
                        alice += evens.pop(0)
            turn = 1 - turn

        if alice > bob:
            print("Alice")
        elif bob > alice:
            print("Bob")
        else:
            print("Tie")

if __name__ == "__main__":
    solve()
"}

