import sys

def count_differing_bits(a, b):
    """Count the number of differing bits between two integers."""
    xor = a ^ b
    count = 0
    while xor:
        count += xor & 1
        xor >>= 1
    return count

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    k = int(data[2])

    armies = []
    for i in range(m + 1):
        armies.append(int(data[3 + i]))

    fedor_army = armies[-1]
    friends = 0

    for i in range(m):
        diff = count_differing_bits(armies[i], fedor_army)
        if diff <= k:
            friends += 1

