    s = data[1] if len(data) > 1 else ""

    result = []
    i = 0
    while i < len(s):
        char = s[i]
        count = 1

        # Count consecutive characters
        while i + count < len(s) and s[i + count] == char:
            count += 1

        # Process the group
        if char in {"a", "e", "i", "o", "u", "y"}:
            # It's a vowel
            if char in {"e", "o"} and count == 2:
                # Exception: keep exactly 2 'e' or 'o'
                result.append(char * 2)
            else:
                # Combine consecutive vowels to one
                result.append(char)
        else:
            # Consonant, keep all
            result.append(char * count)

        i += count

    sys.stdout.write("".join(result))

if __name__ == "__main__":
    solve()
"}

