t = int(input())
for _ in range(t):
    n = int(input())
    a = list(map(int, input().split()))

    # Count even and odd numbers
    even = 0
    odd = 0
    for num in a:
        if num % 2 == 0:
            even += 1
        else:
            odd += 1

    # Game state: (even_count, odd_count, is_alice_turn)
    # We need to determine the optimal outcome

    # If Alice picks optimally, she will try to maximize her score while minimizing Bob's
    # If Bob picks optimally, he will try to maximize his score while minimizing Alice's

    # Let's think recursively
    def game(even, odd, is_alice_turn):
        if even == 0 and odd == 0:
            return (0, 0)  # (Alice_score, Bob_score)

        if is_alice_turn:
            # Alice's turn
            # She should pick an odd number if both exist, otherwise pick the one that gives her the best outcome
            if even > 0 and odd > 0:
                # Pick an odd number (gives Alice 0 points, but prevents Bob from getting it)
                a_score, b_score = game(even, odd - 1, False)
                return (a_score, b_score)
            elif even > 0:
                # Only even numbers left, Alice picks one
                a_score, b_score = game(even - 1, odd, False)
                return (a_score + even, b_score)  # even is the value of the picked number
            else:
