import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if a[i] & a[j]:
                adj[i].append(j)
                adj[j].append(i)

    # Check if any bit appears in ≥ 3 nodes
    bit_count = [0] * 61  # 0 to 60 bits
    for num in a:
        for b in range(61):
            if num & (1 << b):
                bit_count[b] += 1

    # If any bit appears in ≥ 3 nodes, answer is 3
    for b in range(61):
        if bit_count[b] >= 3:
            print(3)
            return

    # Otherwise, check for cycles of length 4
    # Use BFS to find shortest cycle
    visited = [False] * n
    parent = [-1] * n
    dist = [-1] * n

    def bfs(start):
        queue = [start]
        visited[start] = True
        parent[start] = -1
        dist[start] = 0

        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    dist[v] = dist[u] + 1
                    queue.append(v)
                elif parent[u] != v:
                    # Found a cycle
                    return dist[u] + dist[v] + 1
        return -1

    # Run BFS from each unvisited node
    for i in range(n):
        if not visited[i]:
            cycle_len = bfs(i)
            if cycle_len != -1:
