import sys

def solve():
    MOD = 998244353
    n, k = map(int, sys.stdin.readline().split())

    # Count beautiful colorings
    # For n rows, beautiful colorings are determined by a sequence of same/different for adjacent rows
    # This forms a sequence of row blocks
    # Each block is either all white or all black, and blocks alternate colors

    # Number of beautiful colorings: 2 * 2^(n-1) ?
    # Actually, more complex

    # Let's brute force for small n
    if n <= 20:
        from itertools import product

        total = 0
        for color_seq in product([0, 1], repeat=n):  # 0 for white, 1 for black
            # Check if it's beautiful
            is_beautiful = True
            for i in range(n - 1):
                if color_seq[i] == color_seq[i + 1]:
                    # They must be the same in every position
                    # All subsequent rows must be the same
                    if not all(c == color_seq[i] for c in color_seq[i:]):
                        is_beautiful = False
                        break
                else:
                    # They must be different in every position
                    # Opposite color
                    if not all(c == 1 - color_seq[i] for c in color_seq[i:]):
                        is_beautiful = False
                        break
            if is_beautiful:
                # Now check if it's suitable
                is_suitable = True
                # For all rectangles with area >= k of the same color
                # We need to avoid such rectangles
                # A rectangle of all same color means a contiguous block of the same color both row-wise and column-wise

                # Let's find all rectangles
                for i1 in range(n):
                    for i2 in range(i1, n):
                        for j1 in range(n):
                            for j2 in range(j1, n):
                                # Rectangle from (i1,j1) to (i2,j2)
                                # Check if all are the same color
                                color = color_seq[i1]
                                valid = True
                                for i in range(i1, i2 + 1):
                                    for j in range(j1, j2 + 1):
                                        if color_seq[i] != color:
                                            valid = False
                                            break
                                    if not valid:
                                        break
                                if valid:
