                                    if area >= k:
                                        is_suitable = False
                                        break
                            if not is_suitable:
                                break
                        if not is_suitable:
                            break
                    if not is_suitable:
                        break
                if is_suitable:
                    total += 1
        print(total % MOD)
    else:
        print(0)

