def get_primes(limit):
    """Get all primes up to limit using sieve of Eratosthenes"""
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    return [i for i, prime in enumerate(is_prime) if prime]

def smallest_multiple(n, p):
    """Find the smallest multiple of p that is not smaller than n"""
    return ((n + p - 1) // p) * p

def get_predecessors(n, primes):
    """Get all numbers M such that there exists a prime p < M where smallest_multiple(M, p) = n"""
    predecessors = set()
    for p in primes:
        if p >= n:
            continue
        # M must satisfy: p < M <= n and M % p != 0
        # Also, smallest_multiple(M, p) = n
        # smallest_multiple(M, p) = ((M + p - 1) // p) * p = n
        # Let q = ((M + p - 1) // p)
        # Then q * p = n => q = n / p
        # And M <= n < M + p
        # So M must be in (n - p, n]
        # And M % p != 0
        for M in range(n - p + 1, n + 1):
            if M % p != 0 and p < M:
                predecessors.add(M)
    return predecessors

def solve(X2):
    primes = get_primes(X2)

    # Get all possible X1 values that could lead to X2
    X1_set = get_predecessors(X2, primes)

    # For each X1, get all possible X0 values that could lead to X1
    min_X0 = float('inf')
    for X1 in X1_set:
        X0_set = get_predecessors(X1, primes)
        if X0_set:
            min_X0 = min(min_X0, min(X0_set))

    return min_X0

def main():
    X2 = int(input().strip())
    print(solve(X2))

if __name__ == "__main__":
    main()
