def can_select(n, k, s, max_gap):
    """Check if we can select k positions with maximum gap ≤ max_gap"""
    count = 1  # Start from the first position
    pos = 0  # Position of the last selected bar

    # Find the first '0' position
    while pos < n and s[pos] == '1':
        pos += 1

    if pos >= n:
        return False  # No position available

    # Now we start from the first '0' position
    while count < k and pos < n:
        # Find the next position that is either '1' or at distance > max_gap from pos
        next_pos = pos + 1
        while next_pos < n and s[next_pos] == '0' and next_pos - pos - 1 <= max_gap:
            next_pos += 1

        # We can select the next_pos - 1 position
        count += 1
        pos = next_pos

    if count < k:
        return False  # Not enough positions available

    # Check the gap from last selected position to end of workday
    if pos < n and pos - n + 1 > max_gap:
        return False

    return True

def solve():
    n, k = map(int, input().split())
    s = input().strip()

    # Binary search on the answer
    low = 0
    high = n - 1

    while low < high:
        mid = (low + high) // 2

        if can_select(n, k, s, mid):
            high = mid
        else:
            low = mid + 1

    print(low)

