t = int(input())
for _ in range(t):
    n, m = map(int, input().split())
    paths = []
    for _ in range(n):
        paths.append(list(map(int, input().split())))

    # Sort paths at each checkpoint
    for i in range(n):
        paths[i].sort()

    # Initialize assignment matrix
    # assignment[i][j] = path index for runner j at checkpoint i
    assignment = [[0]*m for _ in range(n)]

    # Assign first checkpoint
    for j in range(m):
        assignment[0][j] = j

    # Assign subsequent checkpoints
    for i in range(1, n):
        # Track which paths are used
        used = [False]*m

        # First assign the largest path from this checkpoint
        for j in range(m):
            assignment[i][j] = j
            used[j] = True

        for j in range(m):
            if used[j] and assignment[i][j] == i-1:
                # Found the path that was assigned to this runner
                continue

            for k in range(1, m):
                if not used[k] and assignment[i-1][k] < assignment[i][j] and assignment[i-1][j] > assignment[i][k]:
                    used[k] = True
                    assignment[i][k] = assignment[i][j]
                    assignment[i][j] = -1
                    break

    # Output the results
    for j in range(m):
        line = []
        for i in range(n):
            if assignment[i][j] == j:
                line.append(paths[i][j])
            else:
                for k in range(1, m):
                    if assignment[i][j] == k:
                        line.append(paths[i][k])
                        break
        print(' '.join(map(str, line)))
