import heapq

def is_valid(events):
    n = len(events) // 2
    available = set(range(1, n + 1))
    showcase = []
    for event in events:
        if event[0] == '+':
            if available:
                shuriken = min(available)
                available.remove(shuriken)
                heapq.heappush(showcase, shuriken)
        else:  # event[0] == '-'
            x = int(event[1])
            if not showcase:
                return False
            if showcase[0] != x:
                # The cheapest should be x
                return False
            heapq.heappop(showcase)
    return len(available) == 0 and len(events) // 2 - len(events)//2 == 0

if is_valid(events):
