import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Read edges
    edges = []
    idx = 2
    for _ in range(m):
        u = int(data[idx])
        v = int(data[idx + 1])
        edges.append((u, v))
        idx += 2

    # Union-Find for connectivity
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px

    for u, v in edges:
        union(u, v)

    # Find root of first vertex
    root = find(1)

    # Check if all vertices are connected to root
    connected = True
    for i in range(1, n + 1):
        if find(i) != root:
            connected = False
            break

    # Count degrees (loops count 1, not 2)
    deg = [0] * (n + 1)
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1

    # Degree parity check
    odd_deg = sum(1 for i in range(1, n + 1) if deg[i] % 2 == 1)

    if connected and odd_deg in (0, 2):
        # Answer is sum of C(d, 2) for each vertex
        ans = 0
        for i in range(1, n + 1):
            d = deg[i]
            if d >= 2:
                ans += d * (d - 1) // 2
        print(ans)
    else:
        print(0)

