    non_forbidden = 0
    for i in range(3):
        for j in range(n):
            if grid[i][j] in ('.', 'O'):
                non_forbidden += 1

    # The number of dominoes needed = (non_forbidden - 1) / 2
    num_dominoes = (non_forbidden - 1) // 2

    # We need to count the number of ways to place these dominoes
    # 
    # This is a classic tiling problem
    # 
    # DP[i][state]: i-th column, state represents coverage
    # 
    MOD = 1000000007

    # State representation:
    # 0: No cells covered
    # 1: Top cell covered by vertical domino
    # 2: Middle cell covered by vertical domino
    # 4: Bottom cell covered by vertical domino
    # 5: Top and middle cells covered by horizontal domino
    # 9: Middle and bottom cells covered by horizontal domino
    # 15: All three cells covered by vertical dominoes
    # 
    # Initialize DP
    dp = [0] * 8
    dp[0] = 1

    # Build DP
    for col in range(n):
