    m = int(lines[0].split()[1])

    grid = []
    for i in range(1, n+1):
        row = lines[i].strip()
        grid.append(row)

    # Create bipartite graph
    # For each row, find set of columns it is connected to
    row_to_cols = {}  # row -> set of column indices
    col_to_rows = {}  # column -> set of row indices

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                if i not in row_to_cols:
                    row_to_cols[i] = set()
                row_to_cols[i].add(j)

                if j not in col_to_rows:
                    col_to_rows[j] = set()
                col_to_rows[j].add(i)

    # Check if the bipartite graph is a union of bicliques
    # Each connected component must be a biclique
    visited_rows = set()
    visited_cols = set()

    for start_row in row_to_cols:
        if start_row not in visited_rows:
            queue = [start_row]
            component_rows = {start_row}
            component_cols = set()

            row_set = row_to_cols[start_row]
            # Start with this row's columns
            for col in row_set:
                queue.append(col)
                component_cols.add(col)

            # BFS to find all connected nodes
            visited_rows.add(start_row)

            for item in queue:
                if item in row_to_cols:
                    row = item
                    for col in row_to_cols[row]:
                        if col not in visited_rows:
                            visited_rows.add(row)
                            queue.append(row)
                            component_rows.add(row)
                            component_cols.add(col)
                else:  # item is a column
                    col = item
                    for row in col_to_rows[col]:
                        if row not in visited_cols:
                            visited_cols.add(col)
                            queue.append(col)
                            component_rows.add(row)
                            component_cols.add(col)

            # Check if this component is a biclique
            # For each row in component, its cols must be exactly component_cols
            for row in component_rows:
                if row_to_cols[row] != component_cols:
                    print("No")
                    return

            # For each col in component, its rows must be exactly component_rows
            for col in component_cols:
                if col_to_rows[col] != component_rows:
                    print("No")
                    return

    print("Yes")

if __name__ == "__main__":
    solve()
