    """Recursive function to compute the maximum number of blocks for volume m"""
    if m == 0:
        return (0, 0)

    # Try using a block of size a, where a is the largest cube root <= m
    a = int(m ** (1/3))
    while a ** 3 > m:
        a -= 1

    # Option 1: use the largest cube possible
    blocks1, x1 = max_blocks(m - a ** 3)
    option1_blocks = 1 + blocks1
    option1_x = a ** 3 + x1

    # Option 2: don't use the largest cube, just use smaller cubes
    blocks2, x2 = max_blocks(m - 1)
    option2_blocks = blocks2
    option2_x = x2 + 1

    # Choose the option with more blocks; if tie, choose the one with larger X
    if option1_blocks > option2_blocks:
