def is_beautiful(s, k):
    counts = [0] * 26
    for ch in s:
        counts[ord(ch) - ord('a')] += 1
    for count in counts:
        if count % k != 0:
            return False
    return True

def solve_test_case(n, k, s):
    if is_beautiful(s, k):
        return s

    # Try to find the next beautiful string
    for i in range(n - 1, -1, -1):
        # Try all possible characters from current to 'z'
        for ch in range(ord(s[i]) + 1, ord('z') + 1):
            new_s = s[:i] + chr(ch) + s[i+1:] if i < n-1 else chr(ch)

            # Fill remaining positions with 'a's
            remaining = n - i - 1
            new_s = new_s + 'a' * remaining

            # Check if this new string is beautiful
            if is_beautiful(new_s, k):
                return new_s

    return -1

