def is_strongly_connected(n, m, horizontal, vertical):
    # Create adjacency list
    graph = {}
    for i in range(n):
        for j in range(m):
            graph[(i, j)] = []

            # Check horizontal directions
            if horizontal[i] == '>':
                # Can move east
                if j < m - 1:
                    graph[(i, j)].append((i, j + 1))
            else:  # '<'
                # Can move west
                if j > 0:
                    graph[(i, j)].append((i, j - 1))

            # Check vertical directions
            if vertical[j] == 'v':
                # Can move south
                if i < n - 1:
                    graph[(i, j)].append((i + 1, j))
            else:  # '^'
                # Can move north
                if i > 0:
                    graph[(i, j)].append((i - 1, j))

    # Check strong connectivity
    start = (0, 0)
    visited = set()

    # BFS from start
    queue = [start]
    visited.add(start)
    while queue:
        node = queue.pop(0)
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    # Check if all nodes are visited
    return len(visited) == n * m

def solve():
    n, m = map(int, input().split())
    horizontal = input().strip()
    vertical = input().strip()

    if is_strongly_connected(n, m, horizontal, vertical):
        print("YES")
    else:
        print("NO")

