import itertools

def solve():
    s = input().strip()
    n = len(s)

    # Try all possible combinations of characters to see what's possible
    from collections import Counter

    # Count the original directions
    cnt = Counter(s)

    # We need to end at origin (0, 0)
    # Try all combinations of changing k characters for small k
    for k in range(0, n + 1):
        # Try all ways to change k characters
        # We can only change to 'L', 'R', 'U', 'D'

        # This is too slow for large n, but let's just brute force for now
        # We'll use a bitmask approach for small n
        for mask in range(1 << n):
            if bin(mask).count('1') != k:
                continue

            # Try all possible changes for each character
            total_x = 0
            total_y = 0
            changes = 0

            for i in range(n):
                if mask & (1 << i):
                    # We can change this character to any of 4 directions
                    # Try all 4
                    for d in ['L', 'R', 'U', 'D']:
                        # Count how many of each we would have
                        # Original: cnt[s[i]]
                        # After change: we lose 1 of s[i] and gain 1 of d
                        # We need to ensure we don't exceed the original count
                        if d != s[i]:
                            changes += 1

                        # Update totals
                        if d == 'L':
                            total_x -= 1
                        elif d == 'R':
                            total_x += 1
                        elif d == 'U':
                            total_y += 1
                        elif d == 'D':
