def get_primes(n):
    """Sieve of Eratosthenes to get all primes up to n"""
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return [i for i, prime in enumerate(is_prime) if prime]

def get_reachable_numbers(target, primes):
    """Find all numbers that can reach target in one turn"""
    reachable = set()
    for p in primes:
        # X1 must satisfy: target - p < X1 <= target and p does not divide X1
        for x1 in range(target - p + 1, target + 1):
            if x1 % p != 0:
                reachable.add(x1)
    return reachable

def solve():
    X2 = int(input())

    # Find all primes up to X2
    primes = get_primes(X2)

    # Find all possible X1 values that can reach X2
    possible_x1 = get_reachable_numbers(X2, primes)

    # For each X1, find all possible X0 values that can reach it
    min_x0 = float('inf')
    for x1 in possible_x1:
        # Find all numbers that can reach x1 in one turn
        reachable_x0 = get_reachable_numbers(x1, primes)

        # Find the minimum X0 that is reachable
        for x0 in reachable_x0:
            if x0 >= 3:
                min_x0 = min(min_x0, x0)

    print(min_x0)

