def z_sort(arr):
    """Sort the array to be z-sorted."""
    n = len(arr)

    # Sort the array
    arr.sort()

    # For even indices (0-indexed), we want a high value
    # For odd indices (0-indexed), we want a low value
    # But we need to alternate after the first element too

    # We can achieve this by swapping adjacent elements in pairs
    for i in range(1, n, 2):
        if i < n - 1 and arr[i] < arr[i-1] and arr[i] < arr[i+1]:
            arr[i], arr[i-1] = arr[i-1], arr[i]
        elif i < n - 1 and arr[i] < arr[i-1]:
            arr[i], arr[i+1] = arr[i+1], arr[i]

    return arr

