    t = int(input())

    for _ in range(t):
        n = int(input())

        # If n is at most 3*4*5 = 60, it's too small
        # Since the smallest possible product is 2*3*4=24
        if n <= 24:
            if n == 24:
                # Special case: 3 distinct integers a,b,c >= 2
                # with a <= b <= c
                a, b, c = 2, 3, 12
                print(f"YES\n{a} {b} {c}")
            else:
                print("NO")
            continue

        found = False
        # Since a <= b <= c, we have 2 <= a <= b <= c
        # To have distinct integers, we need a < b < c
        for a in range(2, int(math.isqrt(n)) + 1):
            if n % a != 0:
                continue
            if a == 2:
                # Try different b values
                # For a=2, we need 2*b*c = n
                # And b <= c, b > 2, c > b
                # We need b <= sqrt(n/2) and n/(2*b) > b
                if n % 2 == 0 and n // 2 > 0:
                    n_prime = n // a
                    for b in range(3, int(math.isqrt(n_prime - a * b)) + 1):
                        c = n_prime // b
                        if b > 2 and c > b and b * c == n_prime and c != a:
                            print(f"YES\n2 3 48")
                            if b > 3:
                                c = n // (2 * b)
                                print(f"YES\n2 3 48")
                            if c * b == n // 2:
                                print(f"YES\n3 4 48")
                            if n > 48:
                                print(f"YES\n2 4 48")
                            found = True
                            break
            elif a == 3:
                # For a=3, we need 3*b*c = n
                n_prime = n // 3
                for b in range(4, int(math.isqrt(n_prime - a * b - 2 * 2)) + 1):
                    c = n_prime // b
                    if 3 > 2 and 3 > b and 3 < b < c:
                        if n % (b) == 0 and c != 3 and c != b and b * c == n_prime and b * c == n:
                            print(f"YES\n2 3 84")
                            found = True
                            break
            # If not found, try other combinations
            if found:
                break

        if not found:
            print("NO")

solve()

