        # Sort by weight in descending order
        weights.sort(reverse=True)

        total = 0
        selected = []

        # Try to fill to at least half capacity
        half_capacity = (W + 1) // 2  # Equivalent to ceil(W/2)

        for weight, idx in weights:
            if total + weight > W:
                # Cannot add this item without exceeding capacity
