        # Vertical movement
        if vertical[j] == 'v':
            if i + 1 < n and not visited[i + 1][j]:
                visited[i + 1][j] = True
                queue.append((i + 1, j))
        else:
            if i - 1 >= 0 and not visited[i - 1][j]:
                visited[i - 1][j] = True
                queue.append((i - 1, j))

    # If we can't reach all intersections from (0, 0), return False
    if not all(all(row) for row in visited):
        return False

    # Now check if we can also reach all intersections from (n-1, m-1)
    visited2 = [[False for _ in range(m)] for _ in range(n)]
    queue = deque()

    queue.append((n-1, m-1))
    visited2[n-1][m-1] = True

    while queue:
        i, j = queue.popleft()

        if horizontal[i] == '>':
            if j + 1 < m and not visited2[i][j + 1]:
                visited2[i][j + 1] = True
                queue.append((i, j + 1))
        else:
            if j - 1 >= 0 and not visited2[i][j - 1]:
                visited2[i][j - 1] = True
                queue.append((i, j - 1))

        if vertical[j] == 'v':
            if i + 1 < n and not visited2[i + 1][j]:
                visited2[i + 1][j] = True
                queue.append((i + 1, j))
        else:
            if i - 1 >= 0 and not visited2[i - 1][j]:
                visited2[i - 1][j] = True
                queue.append((i - 1, j))

    # If we can't reach all intersections from (n-1, m-1), return False
    return all(all(row) for row in visited2)

def solve():
    n, m = map(int, input().split())
    horizontal = input().strip()
    vertical = input().strip()

    if is_strongly_connected(n, m, horizontal, vertical):
        print("YES")
    else:
        print("NO")

