import heapq

def solve():
    n = int(input())
    events = []
    for _ in range(2 * n):
        line = input().strip()
        if line[0] == '+':
            events.append(('+', None))
        else:
            _, x = line.split()
            events.append(('-', int(x)))

    # Track which shurikens are available
    available = set()
    # Priority queue of available shurikens
    pq = []

    for event in events:
        if event[0] == '+':
            # We need to determine which shuriken to add
            # We can just add the smallest available shuriken
            # or any unused shuriken
            # Let's just add the smallest unused shuriken
            for i in range(1, n + 1):
                if i not in available:
                    available.add(i)
                    heapq.heappush(pq, i)
                    break
        else:
            # '- x' event
            x = event[1]
            if x not in available:
                print("NO")
                return
            if pq and pq[0] != x:
                print("NO")
                return
            available.remove(x)
            heapq.heappop(pq)

    print("YES")
    # Output the placement order (we can just output the order we added)
    # We need to track the order
    order = []
    for event in events:
        if event[0] == '+':
            # Find which shuriken was added
            for i in range(1, n + 1):
                if i not in available:
                    order.append(i)
                    available.remove(i)
                    break
    print(' '.join(map(str, order)))

