import sys

def solve():
    n = int(sys.stdin.readline())
    p = list(map(int, sys.stdin.readline().split()))

    # Build adjacency list for swap graph
    adj = [[] for _ in range(n)]
    for i in range(n):
        line = sys.stdin.readline().strip()
        for j in range(n):
            if line[j] == '1':
                adj[i].append(j)

    # Find connected components using BFS
    visited = [False] * n
    components = []

    for start in range(n):
        if not visited[start]:
            # BFS to find all nodes in this component
            queue = [start]
            visited[start] = True
            component = []
            while queue:
                node = queue.pop(0)
                component.append(node)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            components.append(component)

    # For each component, collect the values currently in it
    component_values = [[] for _ in range(len(components))]
    for i, node in enumerate(range(n)):
        comp_idx = -1
        for j, comp in enumerate(components):
            if node in comp:
                comp_idx = j
                break
        component_values[comp_idx].append(p[node])

    # Sort values in each component
    for i in range(len(components)):
        component_values[i].sort()

    # Greedily assign the smallest available value to each position
    result = [0] * n
    comp_idx = 0
    comp_ptr = 0

    for pos in range(n):
        # Find which component this position belongs to
        comp_idx = -1
        for j, comp in enumerate(components):
            if pos in comp:
                comp_idx = j
                break

        # Assign the smallest available value from this component
        result[pos] = component_values[comp_idx][comp_ptr]
        comp_ptr += 1

    print(' '.join(map(str, result)))

if __name__ == '__main__':
    solve()
