import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    idx = 1

    # Find the maximum position
    max_pos = 0
    constraints = {}

    for _ in range(n):
        ti = data[idx]
        ki = int(data[idx + 1])
        idx += 2

        for _ in range(ki):
            pos = int(data[idx])
            max_pos = max(max_pos, pos)

            # Add constraint for this position
            if pos not in constraints:
                constraints[pos] = []
            constraints[pos].append(ti[0])

            # Add constraints for the rest of the string
            for i in range(1, len(ti)):
                pos += 1
                if pos not in constraints:
                    constraints[pos] = []
                constraints[pos].append(ti[i])

            idx += 1

    # Build the result
    result = []
    for pos in range(1, max_pos + 1):
        if pos in constraints:
            # There should be exactly one character
            char = constraints[pos][0]
            result.append(char)
        else:
            result.append('a')

    print(''.join(result))

if __name__ == "__main__":
    solve()
