    for _ in range(3):
        line = input().strip()
        board.append(list(line))

    x_count = sum(row.count('X') for row in board)
    o_count = sum(row.count('0') for row in board)

    # Check if board is illegal
    if x_count - o_count > 1 or x_count - o_count < 0:
        print("illegal")
        return

    # Check if both players have winning lines
    x_won = is_win(board, 'X')
    o_won = is_win(board, '0')

    if x_won and o_won:
        print("illegal")
        return

    # Check if X won but it's illegal (X should have one more move than O)
    if x_won and x_count != o_count + 1:
        print("illegal")
        return

    # Check if O won but it's illegal (X and O should have equal moves)
    if o_won and x_count != o_count:
