    # Check if someone has already won
    if x_won:
        print("the first player won")
        return
    if o_won:
        print("the second player won")
        return

    # Check if it's a draw
    if x_count + o_count == 9:
        print("draw")
        return

    # Determine whose turn is next
    if x_count == o_count:
        print("first")
    else:
        print("second")

