import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Compute prefix XOR
    prefix_xor = [0] * (n + 1)
    for i in range(n):
        prefix_xor[i+1] = prefix_xor[i] ^ a[i]

    max_xor = 0
    # Try all pairs (i, j) where 0 <= i < j <= n
    for i in range(n):
        for j in range(i + 1, n + 1):
            current = prefix_xor[i] ^ prefix_xor[j]
            if current > max_xor:
                max_xor = current

    print(max_xor)

if __name__ == "__main__":
    solve()
"}

