import sys

def is_palindrome(s):
    """Check if a string is a palindrome"""
    return s == s[::-1]

def solve():
    s = sys.stdin.readline().strip()
    k = int(sys.stdin.readline())

    if len(s) % k != 0:
        print("NO")
        return

    part_length = len(s) // k

    for i in range(k):
        start = i * part_length
        end = start + part_length
        part = s[start:end]
        if not is_palindrome(part):
            print("NO")
            return

    print("YES")

if __name__ == "__main__":
    solve()
"}

